// xxhash32: xxHash32 (seed 0) of 8 MiB of generated bytes.

const P1: u32 = 0x9E3779B1;
const P2: u32 = 0x85EBCA77;
const P3: u32 = 0xC2B2AE3D;

fn round(acc: u32, w: u32) -> u32 {
    acc.wrapping_add(w.wrapping_mul(P2)).rotate_left(13).wrapping_mul(P1)
}

fn main() {
    let n: i64 = 1 << 23;
    let data: Vec<u8> = (0..n).map(|i| ((i * 2654435761 >> 13) & 255) as u8).collect();
    let word = |p: &[u8]| u32::from_le_bytes([p[0], p[1], p[2], p[3]]);
    let (mut v1, mut v2, mut v3, mut v4) = (P1.wrapping_add(P2), P2, 0u32, 0u32.wrapping_sub(P1));
    for s in data.chunks_exact(16) {
        v1 = round(v1, word(&s[0..]));
        v2 = round(v2, word(&s[4..]));
        v3 = round(v3, word(&s[8..]));
        v4 = round(v4, word(&s[12..]));
    }
    let mut h = v1.rotate_left(1).wrapping_add(v2.rotate_left(7)).wrapping_add(v3.rotate_left(12)).wrapping_add(v4.rotate_left(18)).wrapping_add(n as u32);
    h = (h ^ h >> 15).wrapping_mul(P2);
    h = (h ^ h >> 13).wrapping_mul(P3);
    h ^= h >> 16;
    println!("{h}");
}
